def __new__(cls, dask, name, chunks, dtype=None, meta=None, shape=None):
    self = super().__new__(cls)
    assert isinstance(dask, Mapping)
    if not isinstance(dask, HighLevelGraph):
        dask = HighLevelGraph.from_collections(name, dask, dependencies=())
    self.dask = dask
    self._name = str(name)
    meta = meta_from_array(meta, dtype=dtype)

    # If shape is not provided, try to infer it from the dask graph
    if shape is None:
        # Get all keys for this array
        keys = [k for k in dask.keys() if isinstance(k, tuple) and k[0] == name]
        if not keys:
            raise ValueError("No keys found in dask graph for array")

        # Get the first chunk to determine dimensionality
        first_chunk = dask[keys[0]]
        if hasattr(first_chunk, 'shape'):
            chunk_shape = first_chunk.shape
            ndim = len(chunk_shape)
        else:
            # If chunk doesn't have shape, assume 1D
            ndim = 1

        # Initialize shape with zeros
        shape = [0] * ndim

        # For each key, get its chunk shape and update the total shape
        for key in keys:
            chunk = dask[key]
            if hasattr(chunk, 'shape'):
                chunk_shape = chunk.shape
                for i, s in enumerate(chunk_shape):
                    shape[i] = max(shape[i], key[i+1] * s + s)
            else:
                # For scalar chunks
                shape[0] = max(shape[0], key[1] + 1)

        shape = tuple(shape)

    if (
        isinstance(chunks, str)
        or isinstance(chunks, tuple)
        and chunks
        and any(isinstance(c, str) for c in chunks)
    ):
        dt = meta.dtype
    else:
        dt = None
    self._chunks = normalize_chunks(chunks, shape, dtype=dt)
    if self.chunks is None:
        raise ValueError(CHUNKS_NONE_ERROR_MESSAGE)
    self._meta = meta_from_array(meta, ndim=self.ndim, dtype=dtype)

    # Validate that the shape matches the actual data in the dask graph
    total_size = 1
    for s in shape:
        total_size *= s
    keys = [k for k in dask.keys() if isinstance(k, tuple) and k[0] == name]
    actual_size = 0
    for key in keys:
        chunk = dask[key]
        if hasattr(chunk, 'size'):
            actual_size += chunk.size
        else:
            actual_size += 1  # Scalar chunk
    if total_size != actual_size:
        raise ValueError(f"Shape {shape} implies size {total_size} but actual data size is {actual_size}")
